let pendingCover=null, viewerVideo=null, viewerObjectUrl=null, musicEditId=null, pendingMusicCover1=null, pendingMusicCover2=null, musicQueue=[], musicPlayed=new Set(), musicRandom=false, musicCurrentId=null, draggingCat=null;
function openDB(){return new Promise((res,rej)=>{const r=indexedDB.open(DB_NAME,3);r.onupgradeneeded=()=>{const d=r.result;if(!d.objectStoreNames.contains(STORE))d.createObjectStore(STORE,{keyPath:'id',autoIncrement:true});if(!d.objectStoreNames.contains(CHUNKS))d.createObjectStore(CHUNKS,{keyPath:['itemId','index']})};r.onsuccess=()=>{db=r.result;res(db)};r.onerror=()=>rej(r.error)})}
async function getOPFSFile(path){
  if(!path||!navigator.storage?.getDirectory)return null;
  try{const root=await navigator.storage.getDirectory();const fh=await root.getFileHandle(path);return await fh.getFile()}catch(e){return null}
}
async function reqP(req){return new Promise((res,rej)=>{req.onsuccess=()=>res(req.result);req.onerror=()=>rej(req.error)})}
async function chunkPut(itemId,index,data){const tx=db.transaction(CHUNKS,'readwrite');tx.objectStore(CHUNKS).put({itemId,index,data});return new Promise((res,rej)=>{tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error||new Error('CHUNK_WRITE_FAILED'));tx.onabort=()=>rej(tx.error||new Error('CHUNK_WRITE_ABORTED'))})}
async function deleteChunks(itemId){return new Promise((res,rej)=>{const tx=db.transaction(CHUNKS,'readwrite');const req=tx.objectStore(CHUNKS).openCursor(IDBKeyRange.bound([itemId,0],[itemId,Number.MAX_SAFE_INTEGER]));req.onsuccess=e=>{const c=e.target.result;if(c){c.delete();c.continue()}};tx.oncomplete=()=>res();tx.onerror=()=>rej(tx.error)})}
async function readChunks(itemId,count,type){const chunks=[];const tx=db.transaction(CHUNKS,'readonly');const store=tx.objectStore(CHUNKS);for(let i=0;i<count;i++){const x=await reqP(store.get([itemId,i]));if(!x)throw new Error('MISSING_CHUNK_'+i);chunks.push(x.data)}return new Blob(chunks,{type:type||'application/octet-stream'})}
async function hydrateItem(item){if(item.chunked&&!item.blob){item.blob=await readChunks(item.id,item.chunkCount,item.type)}else if(item.opfsPath&&!item.blob){item.blob=await getOPFSFile(item.opfsPath)}return item}
async function allItems(){return new Promise((res,rej)=>{const r=db.transaction(STORE,'readonly').objectStore(STORE).getAll();r.onsuccess=()=>res(r.result||[]);r.onerror=()=>rej(r.error)})}
async function getItem(id){const raw=await reqP(db.transaction(STORE,'readonly').objectStore(STORE).get(id));if(!raw)throw new Error('ITEM_NOT_FOUND');return hydrateItem(raw)}
const liveUrls=new Set();
function revokeLiveUrls(){for(const u of liveUrls)try{URL.revokeObjectURL(u)}catch(_){}liveUrls.clear()}
async function hydrateGrid(grid){if(!grid)return;const holders=[...grid.querySelectorAll('[data-thumb-id]')];await Promise.all(holders.map(async h=>{try{const item=await getItem(+h.dataset.thumbId);const file=item.coverBlob || item.blob || await (async()=>item.blob||await hydrateItem(item).then(x=>x.blob))();if(!file)return;const url=URL.createObjectURL(file);liveUrls.add(url);if(item.coverBlob || item.type?.startsWith('image/')){const img=document.createElement('img');img.className='thumb';img.src=url;img.alt='';img.loading='lazy';img.decoding='async';img.fetchPriority='low';h.replaceWith(img)}else if(item.type?.startsWith('video/')){const v=document.createElement('video');v.className='thumb';v.src=url;v.muted=true;v.playsInline=true;v.preload='metadata';v.setAttribute('aria-hidden','true');h.replaceWith(v)}else{h.innerHTML='📄'}}catch(e){h.textContent='Không tải được'}}))}
async function writeOPFS(blob,existingPath){
  if(!blob||!navigator.storage?.getDirectory)throw new Error('OPFS_UNAVAILABLE');
  const root=await navigator.storage.getDirectory();
  const path=existingPath||('reze_'+Date.now()+'_'+Math.random().toString(36).slice(2));
  const fh=await root.getFileHandle(path,{create:true});
  const w=await fh.createWritable();
  await w.write(blob);
  await w.close();
  return path;
}
async function put(item){
  const raw=item.id?await reqP(db.transaction(STORE,'readonly').objectStore(STORE).get(item.id)):null;
  if(raw?.chunked||raw?.opfsPath){const copy={...raw,...item};delete copy.blob;return saveMeta(copy)}
  if(raw?.blob){const copy={...raw,...item,blob:raw.blob};return reqP(db.transaction(STORE,'readwrite').objectStore(STORE).put(copy))}
  if(item.blob){return storeFile(new File([item.blob],item.name,{type:item.type||item.blob.type||'application/octet-stream'}),item.category)}
  const copy={...item};delete copy.blob;return saveMeta(copy)
}
async function del(id){const item=await reqP(db.transaction(STORE,'readonly').objectStore(STORE).get(id));if(item?.chunked)try{await deleteChunks(id)}catch(_){}if(item?.opfsPath&&navigator.storage?.getDirectory)try{const root=await navigator.storage.getDirectory();await root.removeEntry(item.opfsPath)}catch(_){}return reqP(db.transaction(STORE,'readwrite').objectStore(STORE).delete(id))}
async function getAppStorageBreakdown(){
  const items=await allItems();
  let images=0,videos=0,files=0,total=0;
  for(const x of items){const n=Number(x.size)||0;total+=n;if(x.type?.startsWith('image/'))images+=n;else if(x.type?.startsWith('video/'))videos+=n;else files+=n}
  return {items,images,videos,files,total};
}
function formatPercent(n){return Number.isFinite(n)?Math.max(0,Math.min(100,n)).toFixed(n>=10?0:1)+'%':'—'}
async function refreshStorageUI(){
  const sub=document.getElementById('storageSub');if(!sub)return;
  const usedEl=document.getElementById('storageUsed'),freeEl=document.getElementById('storageFree'),quotaEl=document.getElementById('storageQuota'),bar=document.getElementById('storageBarFill');
  try{
    const own=await getAppStorageBreakdown();
    document.getElementById('storageImages').textContent=formatSize(own.images);
    document.getElementById('storageVideos').textContent=formatSize(own.videos);
    document.getElementById('storageFiles').textContent=formatSize(own.files);
    let est=null;
    if(navigator.storage?.estimate){try{est=await navigator.storage.estimate()}catch(e){}}
    if(est?.quota){
      const usage=Number(est.usage)||0, quota=Number(est.quota)||0, free=Math.max(0,quota-usage), pct=quota?usage/quota*100:0;
      usedEl.textContent=formatSize(usage);freeEl.textContent=formatSize(free);quotaEl.textContent=formatSize(quota);bar.style.width=Math.min(100,pct)+'%';
      sub.textContent=`Trình duyệt ước tính ${formatPercent(pct)} quota đang được dùng. Số liệu là ước tính.`;
    }else{
      usedEl.textContent=formatSize(own.total);freeEl.textContent='Không xác định';quotaEl.textContent='Không xác định';bar.style.width='0%';
      sub.textContent=`Nội dung của web đang chiếm khoảng ${formatSize(own.total)}. Brave không cung cấp quota ước tính cho địa chỉ HTTP này.`;
    }
  }catch(e){sub.textContent='Không đọc được thông tin bộ nhớ lúc này.';console.error(e)}
}
async function prepareStorage(){try{if(navigator.storage?.persist)await navigator.storage.persist()}catch(e){}try{if(navigator.storage?.estimate){const q=await navigator.storage.estimate();console.log('Storage',q)}}catch(e){}}
async function saveMeta(item){const copy={...item};delete copy.blob;return reqP(db.transaction(STORE,'readwrite').objectStore(STORE).put(copy))}
async function storeFile(file,category){
  if(!file||!category)throw new Error('INVALID_FILE');
  const item={name:file.name.replace(/\.[^.]+$/,'')||file.name,description:'',category,rank:'',type:file.type||'application/octet-stream',size:file.size,createdAt:Date.now(),storage:'pending'};
  try{
    if(navigator.storage?.estimate){const est=await navigator.storage.estimate();const free=Math.max(0,(Number(est.quota)||0)-(Number(est.usage)||0));if(free && file.size>Math.max(0,free-8*1024*1024))throw new Error('STORAGE_SPACE_LOW');}
  }catch(e){if(e?.message==='STORAGE_SPACE_LOW')throw e}
  const id=await reqP(db.transaction(STORE,'readwrite').objectStore(STORE).add(item));
  const statusEl=document.getElementById('uploadStatus');
  try{
    // Prefer OPFS: stream the selected file directly instead of creating one huge Blob in memory.
    if(navigator.storage?.getDirectory){
      let path='reze_'+id+'_'+Date.now()+'_'+Math.random().toString(36).slice(2);
      try{
        const root=await navigator.storage.getDirectory();
        const fh=await root.getFileHandle(path,{create:true});
        const writable=await fh.createWritable();
        const reader=file.stream().getReader();let written=0;
        try{while(true){const {done,value}=await reader.read();if(done)break;await writable.write(value);written+=value.byteLength;if(statusEl)statusEl.textContent=`Đang thêm ${file.name} · ${Math.round(written/file.size*100)}%`}}finally{reader.releaseLock()}
        await writable.close();
        item.opfsPath=path;item.storage='opfs';delete item.chunked;delete item.chunkCount;await saveMeta({...item,id});return id;
      }catch(opfsErr){try{const root=await navigator.storage.getDirectory();await root.removeEntry(path)}catch(_){}console.warn('OPFS failed, falling back to chunks',opfsErr)}
    }
    item.chunked=true;item.chunkCount=Math.max(1,Math.ceil(file.size/CHUNK_SIZE));item.storage='chunks';await saveMeta({...item,id});
    for(let i=0;i<item.chunkCount;i++){const buf=await file.slice(i*CHUNK_SIZE,Math.min(file.size,(i+1)*CHUNK_SIZE)).arrayBuffer();await chunkPut(id,i,buf);if(statusEl)statusEl.textContent=`Đang thêm ${file.name} · ${Math.round((i+1)/item.chunkCount*100)}%`}
    return id;
  }catch(e){
    try{if(item.chunked)await deleteChunks(id)}catch(_){}
    try{if(item.opfsPath&&navigator.storage?.getDirectory){const root=await navigator.storage.getDirectory();await root.removeEntry(item.opfsPath)}}catch(_){}
    try{await reqP(db.transaction(STORE,'readwrite').objectStore(STORE).delete(id))}catch(_){}
    throw e;
  }
}
function showModal(id){document.getElementById(id).classList.add('show')}
function hideModal(id){document.getElementById(id).classList.remove('show');if(id==='viewerModal'){if(viewerVideo){try{viewerVideo.pause()}catch(_){}viewerVideo=null}if(viewerObjectUrl){try{URL.revokeObjectURL(viewerObjectUrl)}catch(_){}viewerObjectUrl=null}document.getElementById('viewer').innerHTML='';const ma=document.getElementById('musicAudio');if(ma&&!ma.paused){stopVideo2Audio();}else ensureVideo2Playing()}}
function escapeHtml(s){return String(s||'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function formatSize(n){if(!n)return '';const u=['B','KB','MB','GB'];let i=0,x=n;while(x>=1024&&i<u.length-1){x/=1024;i++}return (i?x.toFixed(x>=10?0:1):x.toFixed(0))+' '+u[i]}
function typeLabel(item){if(item.type?.startsWith('image/'))return 'ẢNH';if(item.type?.startsWith('video/'))return 'VIDEO';return 'FILE'}
function formatTime(sec){sec=Number(sec);if(!Number.isFinite(sec)||sec<0)return '0:00';const m=Math.floor(sec/60),s=Math.floor(sec%60);return m+':'+String(s).padStart(2,'0')}
function parseLyrics(raw,duration){const text=String(raw||'').replace(/\r/g,'').trim();if(!text)return [];const lines=text.split('\n').map(x=>x.trim()).filter(Boolean);const timed=[];for(const line of lines){const m=line.match(/^\s*\[(\d{1,2}):(\d{2}(?:\.\d{1,3})?)\]\s*(.*)$/);if(m)timed.push({time:Number(m[1])*60+Number(m[2]),text:m[3]||'♪'});}if(timed.length){timed.sort((a,b)=>a.time-b.time);return timed.map((x,i)=>({time:x.time,text:x.text,end:i+1<timed.length?timed[i+1].time:Math.max(duration||x.time+8,x.time+8)}))}const step=Number(duration)>0?Number(duration)/lines.length:8;return lines.map((text,i)=>({time:i*step,text,end:(i+1)*step}))}
async function renderLyrics(item){const panel=document.getElementById('musicLyrics'),linesEl=document.getElementById('lyricsLines');if(!panel||!linesEl)return;const audio=document.getElementById('musicAudio');document.getElementById('lyricsTitle').textContent=musicMetaName(item);document.getElementById('lyricsAuthor').textContent=musicAuthor(item);const cover=document.getElementById('lyricsCover');if(cover.dataset.url)try{URL.revokeObjectURL(cover.dataset.url)}catch(_){}if(item.coverBlob){const u=URL.createObjectURL(item.coverBlob);cover.dataset.url=u;cover.src=u}else{delete cover.dataset.url;cover.removeAttribute('src')}const parsed=parseLyrics(item.lyrics,audio.duration);linesEl.innerHTML=parsed.length?parsed.map((x,i)=>`<div class="lyric-line" data-lyric-index="${i}">${escapeHtml(x.text)}</div>`).join(''):'<div class="lyrics-empty">Chưa có lyric. Vào Chỉnh sửa bài hát để thêm lời.</div>';panel.classList.remove('hidden');panel._lyrics=parsed;updateLyricsHighlight()}
function updateLyricsHighlight(){const panel=document.getElementById('musicLyrics'),linesEl=document.getElementById('lyricsLines'),audio=document.getElementById('musicAudio');if(!panel||panel.classList.contains('hidden')||!panel._lyrics)return;const t=Number(audio.currentTime)||0;let active=-1;panel._lyrics.forEach((x,i)=>{if(t>=x.time&&(i===panel._lyrics.length-1||t<x.end))active=i});[...linesEl.children].forEach((el,i)=>{el.classList.toggle('active',i===active);el.classList.toggle('past',active>=0&&i<active)});if(active>=0){const el=linesEl.children[active];if(el)panel.scrollTo({top:Math.max(0,el.offsetTop-panel.clientHeight*.35),behavior:'smooth'})}}
async function loadBackgroundVideo(){const key=localStorage.getItem(BG_VIDEO_KEY);if(!key)return;try{const item=await getItem(Number(key));const hydrated=await hydrateItem(item);if(!hydrated.blob)return;const url=URL.createObjectURL(hydrated.blob);v2.dataset.customUrl=url;v2.src=url;document.getElementById('backgroundFileName').textContent='Đang dùng: '+(item.name||'Video nền tùy chỉnh');v2.load()}catch(e){localStorage.removeItem(BG_VIDEO_KEY)}}
async function setBackgroundVideo(file){if(!file||!file.type.startsWith('video/'))return;const oldId=Number(localStorage.getItem(BG_VIDEO_KEY));if(oldId)try{await del(oldId)}catch(_){}const id=await storeFile(file,'Background');localStorage.setItem(BG_VIDEO_KEY,String(id));const item=await getItem(id);const hydrated=await hydrateItem(item);if(hydrated.blob){if(v2.dataset.customUrl)try{URL.revokeObjectURL(v2.dataset.customUrl)}catch(_){}const url=URL.createObjectURL(hydrated.blob);v2.dataset.customUrl=url;v2.src=url;v2.loop=true;v2.currentTime=0;v2.load();await ensureVideo2Playing()}document.getElementById('backgroundFileName').textContent='Đang dùng: '+file.name}
async function resetBackgroundVideo(){const id=Number(localStorage.getItem(BG_VIDEO_KEY));if(id)try{await del(id)}catch(_){}localStorage.removeItem(BG_VIDEO_KEY);if(v2.dataset.customUrl)try{URL.revokeObjectURL(v2.dataset.customUrl)}catch(_){}delete v2.dataset.customUrl;v2.src='./Reze_Yen_Binh.mp4';v2.loop=true;v2.currentTime=0;v2.load();document.getElementById('backgroundFileName').textContent='Đang dùng Reze Yên Bình';await ensureVideo2Playing()}
function syncMusicButton(){const b=document.getElementById('musicToggle'),t=document.getElementById('musicStateText');if(!b)return;b.textContent=musicEnabled?'🔊':'🔇';b.title=musicEnabled?'Tắt nhạc nền':'Bật nhạc nền';if(t)t.textContent=musicEnabled?'Nhạc nền đang bật · Chuyển mục không làm nhạc dừng.':'Nhạc nền đang tắt · Chuyển mục sẽ không tự bật lại âm thanh.';b.classList.toggle('active',!musicEnabled)}
