async function showMiniMusic(item){const mini=document.getElementById('musicMini');if(!mini)return;document.getElementById('miniTitle').textContent=musicMetaName(item);document.getElementById('miniAuthor').textContent=musicAuthor(item);const img=document.getElementById('miniCover');if(img.dataset.url)try{URL.revokeObjectURL(img.dataset.url)}catch(_){}img.dataset.url='';if(item.coverBlob){const u=URL.createObjectURL(item.coverBlob);img.src=u;img.dataset.url=u}else img.removeAttribute('src');mini.classList.remove('hidden','sink');mini.classList.add('linger');document.getElementById('miniPlay').textContent=document.getElementById('musicAudio').paused?'▶':'❚❚';app.classList.add('music-playing')}
