let audioCtx=null,lastUiSoundAt=0;
function uiSound(kind='tap'){try{const now=performance.now();if(now-lastUiSoundAt<55)return;lastUiSoundAt=now;if(!window.AudioContext&&!window.webkitAudioContext)return;audioCtx=audioCtx||new (window.AudioContext||window.webkitAudioContext)();if(audioCtx.state==='suspended')audioCtx.resume();const o=audioCtx.createOscillator(),g=audioCtx.createGain();o.type='sine';o.frequency.value=kind==='open'?620:kind==='nav'?480:720;g.gain.setValueAtTime(.0001,audioCtx.currentTime);g.gain.exponentialRampToValueAtTime(.035,audioCtx.currentTime+.008);g.gain.exponentialRampToValueAtTime(.0001,audioCtx.currentTime+.085);o.connect(g).connect(audioCtx.destination);o.start();o.stop(audioCtx.currentTime+.09)}catch(e){}}
function playViewTransition(title,isCategory=false){const el=document.getElementById('viewTransition'),t=document.getElementById('vtTitle');t.textContent=title;t.classList.toggle('long-category',!!isCategory&&String(title).length>14);el.classList.toggle('category-mode',!!isCategory);el.classList.remove('run');void el.offsetWidth;el.classList.add('run');setTimeout(()=>el.classList.remove('run'),isCategory?1100:780)}
const NOTES_KEY='reze_home_notes_v1';
function getHomeNotes(){try{const a=JSON.parse(localStorage.getItem(NOTES_KEY)||'[]');return Array.isArray(a)?a.filter(x=>typeof x==='string'&&x.trim()):[]}catch(_){return []}}
function saveHomeNotes(a){localStorage.setItem(NOTES_KEY,JSON.stringify(a.slice(0,100)))}
function cleanNoteText(v){return String(v||'').trim().replace(/^[“”"']+|[“”"']+$/g,'').trim()}
function showRandomHomeQuote(){const el=document.getElementById('homeQuote');if(!el)return;const notes=getHomeNotes();if(!notes.length){el.classList.add('hidden');el.innerHTML='';return}const chosen=cleanNoteText(notes[Math.floor(Math.random()*notes.length)]);el.classList.remove('hidden');el.innerHTML='<span class="quote-text">&quot; '+escapeHtml(chosen)+'&quot;</span>';el.classList.remove('quote-refresh');void el.offsetWidth;el.classList.add('quote-refresh')}
function renderHomeNotes(){const list=document.getElementById('notesList');if(!list)return;const notes=getHomeNotes();list.innerHTML=notes.length?notes.map((x,i)=>`<div class="note-item" data-note-row="${i}"><span class="note-display">${escapeHtml(cleanNoteText(x))}</span><textarea class="note-edit-input hidden" rows="2">${escapeHtml(cleanNoteText(x))}</textarea><div class="note-actions"><button type="button" data-note-edit="${i}" aria-label="Chỉnh sửa câu">✎</button><button type="button" data-note-save="${i}" class="hidden" aria-label="Lưu câu">✓</button><button type="button" data-note-cancel="${i}" class="hidden" aria-label="Hủy">×</button><button type="button" data-note-del="${i}" aria-label="Xóa câu">⌫</button></div></div>`).join(''):'<div class="notes-empty">Chưa có câu nào. Thêm vài câu để các đề mục chọn ngẫu nhiên.</div>'}
function bindHomeNotes(){const viewBtn=document.getElementById('notesViewBtn'),savedPanel=document.getElementById('notesSavedPanel');if(viewBtn&&savedPanel){viewBtn.onclick=()=>{savedPanel.classList.toggle('hidden');viewBtn.textContent=savedPanel.classList.contains('hidden')?'Xem':'Ẩn';uiSound('tap')}}const add=document.getElementById('noteAddBtn'),input=document.getElementById('noteInput'),list=document.getElementById('notesList');if(!add||!input||!list)return;add.onclick=()=>{const value=cleanNoteText(input.value);if(!value)return;const notes=getHomeNotes();notes.push(value);saveHomeNotes(notes);input.value='';renderHomeNotes();showRandomHomeQuote();uiSound('tap')};input.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter')add.click()});list.onclick=e=>{const edit=e.target.closest('[data-note-edit]'),save=e.target.closest('[data-note-save]'),cancel=e.target.closest('[data-note-cancel]'),del=e.target.closest('[data-note-del]');const row=e.target.closest('[data-note-row]');if(!row)return;const i=Number(row.dataset.noteRow);const notes=getHomeNotes();if(edit){uiSound('tap');row.querySelector('.note-display')?.classList.add('hidden');row.querySelector('.note-edit-input')?.classList.remove('hidden');row.querySelector('[data-note-edit]')?.classList.add('hidden');row.querySelector('[data-note-del]')?.classList.add('hidden');row.querySelector('[data-note-save]')?.classList.remove('hidden');row.querySelector('[data-note-cancel]')?.classList.remove('hidden');row.querySelector('.note-edit-input')?.focus();return}if(save){const v=cleanNoteText(row.querySelector('.note-edit-input')?.value);if(!v)return;notes[i]=v;saveHomeNotes(notes);renderHomeNotes();showRandomHomeQuote();uiSound('tap');return}if(cancel){renderHomeNotes();return}if(del){notes.splice(i,1);saveHomeNotes(notes);renderHomeNotes();showRandomHomeQuote();uiSound('tap')}};renderHomeNotes()}
bindHomeNotes();
function switchView(id){const labels={homeView:'Home',searchView:'Search',musicView:'Music',achievementsView:'Achievements',youView:'You',categoryView:currentCat||'Category'};const wasMusic=currentView==='musicView'&&id!=='musicView';uiSound('nav');showRandomHomeQuote();playViewTransition(labels[id]||'',id==='categoryView');currentView=id;views.forEach(v=>v.classList.toggle('active',v.id===id));document.querySelectorAll('.bottom-nav button').forEach(b=>b.classList.toggle('active',b.dataset.view===id));window.scrollTo({top:0,behavior:'auto'});document.documentElement.scrollTop=0;document.body.scrollTop=0;if(id!=='categoryView'){editMode=false;rankMode=false;selected.clear();document.getElementById('categoryView').classList.remove('edit-on','rank-mode')}closeMusicSearch();syncMusicButton();ensureVideo2Playing();if(wasMusic){const mini=document.getElementById('musicMini');if(mini&&!mini.classList.contains('hidden')){mini.classList.remove('sink');mini.classList.add('linger');clearTimeout(window.__miniSinkTimer);window.__miniSinkTimer=setTimeout(()=>{mini.classList.remove('linger');mini.classList.add('sink');setTimeout(()=>{mini.classList.add('hidden');app.classList.remove('music-playing')},600)},2000)}}if(id==='musicView'){const mini=document.getElementById('musicMini');if(mini&&!document.getElementById('musicAudio').paused){mini.classList.remove('hidden','sink');mini.classList.add('linger');app.classList.add('music-playing')}}if(id==='youView')refreshStorageUI();if(id==='musicView'){syncAllSameNameMusic().then(()=>renderMusicList())}}
function makeThumb(item){if(item.coverBlob || item.blob){return `<div class="thumb media-placeholder" data-thumb-id="${item.id}">${item.type?.startsWith('video/')?'VIDEO':item.type?.startsWith('image/')?'ẢNH':'📄'}</div>`}if(item.type?.startsWith('image/'))return `<div class="thumb media-placeholder" data-thumb-id="${item.id}">ẢNH</div>`;if(item.type?.startsWith('video/'))return `<div class="thumb media-placeholder" data-thumb-id="${item.id}">VIDEO</div>`;return `<div class="thumb media-placeholder" data-thumb-id="${item.id}" style="display:grid;place-items:center;font-size:36px">📄</div>`}
function card(item,opts={}){const rank=item.rank?`<span class="rank-badge ${item.rank.toLowerCase()}">${item.rank}</span>`:'';const add=opts.rankMode?`<button class="rank-add" data-rank-add="${item.id}" title="Thêm vào ${rankFilter}">＋</button>`:'';const desc=item.description?`<div class="desc">${escapeHtml(item.description)}</div>`:'';const fileInfo=!item.type?.startsWith('image/')&&!item.type?.startsWith('video/')?`<div class="file-info"><span>${escapeHtml(item.type||'File')}</span><span>${formatSize(item.size||item.blob?.size)}</span></div>`:'';return `<article class="media-card ${selected.has(item.id)?'selected':''}" data-id="${item.id}" style="--i:${opts.index||0}">${makeThumb(item)}${rank}${add}<span class="type-badge">${typeLabel(item)}</span><input class="check" type="checkbox" data-check="${item.id}" ${selected.has(item.id)?'checked':''}><div class="meta"><div class="name">${escapeHtml(item.name)}</div>${desc}<div class="sub">${escapeHtml(item.category)} · ${new Date(item.createdAt).toLocaleDateString('vi-VN')}</div>${fileInfo}</div></article>`}
async function renderCategory(){revokeLiveUrls();const items=(await allItems()).filter(x=>x.category===currentCat);let shown=items;if(currentCat==='NSFW'&&rankFilter)shown=items.filter(x=>x.rank===rankFilter);document.getElementById('catEyebrow').textContent=currentCat.toUpperCase();document.getElementById('catTitle').textContent=currentCat;document.getElementById('catDesc').textContent=currentCat==='NSFW'?'Kho NSFW — chọn SSR / S / A / B / C để lọc.':'Kho nội dung riêng của mày.';document.getElementById('rankTabs').classList.toggle('hidden',currentCat!=='NSFW');document.getElementById('rankTabs').querySelectorAll('.rank-tab').forEach(b=>b.classList.toggle('active',b.dataset.rank===rankFilter));const grid=document.getElementById('mediaGrid');grid.innerHTML=shown.length?shown.map((x,i)=>card(x,{rankMode:rankMode&&currentCat==='NSFW',index:i})).join(''):'';document.getElementById('empty').classList.toggle('hidden',shown.length>0);document.getElementById('toolbar').querySelector('#selectedCount').textContent=selected.size+' đã chọn';document.getElementById('categoryView').classList.toggle('edit-on',editMode);document.getElementById('categoryView').classList.toggle('rank-mode',rankMode);await hydrateGrid(grid)}
async function renderSearch(){revokeLiveUrls();const q=document.getElementById('searchInput').value.trim().toLowerCase();const items=(await allItems()).filter(x=>x.category!=='Background');const shown=q?items.filter(x=>(x.name+' '+(x.description||'')+' '+x.category).toLowerCase().includes(q)):items;const grid=document.getElementById('searchGrid');grid.innerHTML=shown.length?shown.map((x,i)=>card(x,{index:i})).join(''):'<div class="empty" style="grid-column:1/-1">Không tìm thấy.</div>';await hydrateGrid(grid)}
async function renderAchievements(){revokeLiveUrls();const items=(await allItems()).filter(x=>x.category==='Achievements');document.getElementById('achievementGrid').innerHTML=items.map((x,i)=>card(x,{index:i})).join('');document.getElementById('achievementEmpty').classList.toggle('hidden',items.length>0);await hydrateGrid(document.getElementById('achievementGrid'))}
function goHome(){switchView('homeView')}
function openCategory(cat){currentCat=cat;rankFilter='';rankMode=false;editMode=false;selected.clear();switchView('categoryView');renderCategory()}
async function openItem(item){
  const viewer=document.getElementById('viewer');
  if(viewerVideo){try{viewerVideo.pause()}catch(_){}viewerVideo=null}
  if(viewerObjectUrl){try{URL.revokeObjectURL(viewerObjectUrl)}catch(_){}viewerObjectUrl=null}
  const ma=document.getElementById('musicAudio');if(ma){try{ma.pause()}catch(_){} }
  if(item.type?.startsWith('video/')){
    v2.muted=true;v2.volume=0;
    viewerObjectUrl=URL.createObjectURL(item.blob);
    viewer.innerHTML=`<div style="text-align:center"><video id="activeViewerVideo" src="${viewerObjectUrl}" controls autoplay playsinline webkit-playsinline preload="auto"></video><div style="margin-top:10px;color:#aaa;font-size:11px">${escapeHtml(item.description||'')}</div></div>`;
    viewerVideo=document.getElementById('activeViewerVideo');
    viewerVideo.muted=false;viewerVideo.volume=1;
    try{await viewerVideo.play()}catch(_){viewerVideo.controls=true}
  }else if(item.type?.startsWith('image/')){
    viewerObjectUrl=URL.createObjectURL(item.blob);
    viewer.innerHTML=`<div style="text-align:center"><img src="${viewerObjectUrl}" alt="${escapeHtml(item.name)}" decoding="async"><div style="margin-top:10px;color:#aaa;font-size:11px">${escapeHtml(item.description||'')}</div></div>`;
  }else{
    viewerObjectUrl=URL.createObjectURL(item.blob);
    viewer.innerHTML=`<div class="panel viewer-file"><h2>${escapeHtml(item.name)}</h2><p style="color:#999">${escapeHtml(item.description||item.type||'File')}</p><a href="${viewerObjectUrl}" download="${escapeHtml(item.name)}"><button>Tải file</button></a></div>`;
  }
  showModal('viewerModal');
}
async function openEditModal(item){editingId=item.id;pendingCover=item.coverBlob||null;document.getElementById('editName').value=item.name||'';document.getElementById('editDesc').value=item.description||'';document.getElementById('editCategory').value=item.category;document.getElementById('editRank').value=item.rank||'';document.getElementById('rankEditField').style.display=item.category==='NSFW'?'block':'none';const preview=document.getElementById('coverPreview');if(preview.dataset.url){try{URL.revokeObjectURL(preview.dataset.url)}catch(_){}}delete preview.dataset.url;if(pendingCover){const u=URL.createObjectURL(pendingCover);preview.dataset.url=u;preview.src=u;preview.classList.remove('hidden')}else{preview.removeAttribute('src');preview.classList.add('hidden')}showModal('editModal')}
