async function handleGridClick(e){const rankAdd=e.target.closest('[data-rank-add]');if(rankAdd){e.stopPropagation();const id=+rankAdd.dataset.rankAdd;const item=(await allItems()).find(x=>x.id===id);if(item){item.rank=rankFilter;await put(item);renderCategory()}return}const check=e.target.closest('[data-check]');if(check){e.stopPropagation();const id=+check.dataset.check;if(check.checked)selected.add(id);else selected.delete(id);renderCategory();return}const cardEl=e.target.closest('.media-card');if(!cardEl)return;const id=+cardEl.dataset.id;const item=(await allItems()).find(x=>x.id===id);if(!item)return;if(editMode){await openEditModal(await getItem(id))}else{uiSound('open');openItem(await getItem(id))}}
async function addFiles(fileList,category){if(!category){alert('Hãy mở một danh mục trước khi thêm nội dung.');return 0}const files=[...fileList];if(!files.length)return 0;let added=0,failed=[];await prepareStorage();for(const file of files){try{await storeFile(file,category);added++}catch(err){failed.push(file.name);console.error('Upload failed',file.name,err)}}await renderCategory();await renderSearch();await renderAchievements();if(failed.length){const reason=failed.length===files.length?'\n\nCó thể quota của website đã gần đầy. Vào You → Bộ nhớ website để kiểm tra.':'';alert(`Đã thêm ${added}/${files.length} tệp.\nKhông thêm được: ${failed.join(', ')}${reason}`)}return added}
