document.getElementById('coverPickBtn').onclick=()=>openPicker(document.getElementById('coverInput'));document.getElementById('coverRemoveBtn').onclick=()=>{pendingCover=null;clearCoverPreview()};document.getElementById('coverInput').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;if(!f.type.startsWith('image/')){alert('Chọn một file ảnh làm ảnh bìa.');e.target.value='';return}pendingCover=new Blob([await f.arrayBuffer()],{type:f.type});const p=document.getElementById('coverPreview');if(p.dataset.url){try{URL.revokeObjectURL(p.dataset.url)}catch(_){}}const u=URL.createObjectURL(pendingCover);p.dataset.url=u;p.src=u;p.classList.remove('hidden');e.target.value=''};
