const categorySortExit=document.getElementById('categorySortExit');
let sortPointerId=null,sortDragEl=null,sortGhost=null,sortPlaceholder=null,sortLongPressTimer=0,sortStartX=0,sortStartY=0,sortDragOffsetY=0,sortFixedLeft=0,sortActive=false,sortJustActivated=false,sortModeArmed=false;
