// Music controls
function cleanMusicDisplayName(s){
  let x=String(s||'').replace(/\.[a-z0-9]{2,6}$/i,'').trim();
  x=x.replace(/[\[\(\{][^\]\)\}]*?(?:review|preview|snippet|demo|teaser|full|official|audio|video|lyrics?|lyric|hq|original)[^\]\)\}]*[\]\)\}]/gi,' ');
  x=x.replace(/(?:^|[\s._-])(?:review|preview|snippet|demo|teaser|full|official|audio|video|lyrics?|lyric|hq|original)(?=$|[\s._-])/gi,' ');
  return x.replace(/[_|]+/g,' ').replace(/\s+/g,' ').trim();
}
function normalizeMusicKey(s){
  let x=String(s||'').normalize('NFKC').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
  x=x.replace(/\.[a-z0-9]{2,6}$/i,'');
  x=x.replace(/[\[\(\{][^\]\)\}]*?(?:review|preview|snippet|demo|teaser|full|official|audio|video|lyrics?|lyric|hq|original)[^\]\)\}]*[\]\)\}]/gi,' ');
  x=x.replace(/(?:^|[\s._-])(?:review|preview|snippet|demo|teaser|full|official|audio|video|lyrics?|lyric|hq|original)(?=$|[\s._-])/gi,' ');
  x=x.replace(/[‘’´`]/g,"'").replace(/[“”]/g,'"');
  x=x.replace(/[_|]+/g,' ');
  x=x.replace(/[^a-z0-9'&]+/g,' ').trim().replace(/\s+/g,' ');
  return x;
}
function musicHasLocalAudio(item){return !!item && !item.remoteUrl && ((Number(item.size)||0)>0 || !!item.opfsPath || !!item.chunked || !!item.blob)}
function musicIsReview(item){
  if(!item)return false;
  const n=String(item.name||'');
  return !!item.remoteUrl || item.source==='review' || /(?:^|[\s_\-\[\(])(?:review|preview|snippet|demo|teaser)(?:$|[\s_\-\]\)])/i.test(n) || /preview|review/i.test(String(item.description||''));
}
function musicFullScore(item){
  let score=0;
  if(musicHasLocalAudio(item))score+=100;
  if(!musicIsReview(item))score+=20;
  if(/(?:^|[\s_\-\[\(])full(?:$|[\s_\-\]\)])/i.test(String(item.name||'')))score+=15;
  if(/(?:official|original|hq|flac|wav|lossless)/i.test(String(item.name||'')))score+=3;
  if(musicIsReview(item))score-=100;
  return score;
}
function musicMetaRichness(item){return (item?.coverBlob?4:0)+(item?.coverBlob2?2:0)+(item?.lyrics?3:0)+(item?.author?2:0)+(item?.description?1:0)}
function itemLooksLikeReviewName(name){return /(?:^|[\s_\-\[\(])(?:review|preview|snippet|demo|teaser)(?:$|[\s_\-\]\)])/i.test(String(name||''))}
function musicNameSame(a,b){const x=normalizeMusicKey(a),y=normalizeMusicKey(b);return !!x&&!!y&&x===y}
async function findMusicSameName(name){const key=normalizeMusicKey(name);if(!key)return [];return (await getMusicItems()).filter(x=>normalizeMusicKey(x.name)===key)}
async function syncAllSameNameMusic(){
  const items=await getMusicItems();
  const groups=new Map();
  for(const item of items){
    const key=normalizeMusicKey(item.name);
    if(!key)continue;
    if(!groups.has(key))groups.set(key,[]);
    groups.get(key).push(item);
  }
  let removed=0;
  for(const group of groups.values()){
    if(group.length<2)continue;
    const locals=group.filter(musicHasLocalAudio);
    const canonical=(locals.length?locals:group).slice().sort((a,b)=>
      (musicFullScore(b)-musicFullScore(a))||
      (musicMetaRichness(b)-musicMetaRichness(a))||
      ((Number(b.size)||0)-(Number(a.size)||0))||
      ((b.createdAt||0)-(a.createdAt||0))
    )[0];
    const metaSource=group.slice().sort((a,b)=>
      (musicMetaRichness(b)-musicMetaRichness(a))||((b.createdAt||0)-(a.createdAt||0))
    )[0];
    const oldCurrent=group.find(x=>x.id===musicCurrentId);
    const audio=document.getElementById('musicAudio');
    const oldTime=oldCurrent&&audio?.src?(audio.currentTime||0):0;
    if(metaSource && metaSource.id!==canonical.id){
      canonical.name=metaSource.name||canonical.name;
      canonical.author=metaSource.author||canonical.author||'Không rõ tác giả';
      canonical.description=metaSource.description||canonical.description||'';
      canonical.lyrics=metaSource.lyrics||canonical.lyrics||'';
      if(!canonical.coverBlob&&metaSource.coverBlob)canonical.coverBlob=metaSource.coverBlob;
      if(!canonical.coverBlob2&&metaSource.coverBlob2)canonical.coverBlob2=metaSource.coverBlob2;
      if(canonical.musicOrder==null&&metaSource.musicOrder!=null)canonical.musicOrder=metaSource.musicOrder;
    }
    canonical.name=cleanMusicDisplayName(canonical.name)||canonical.name;
    if(locals.length){canonical.source='full';canonical.remoteUrl='';canonical.syncedAt=Date.now()}
    await saveMeta(canonical);
    for(const other of group){
      if(other.id===canonical.id)continue;
      try{await del(other.id);removed++}catch(e){console.error('Music dedupe delete failed',other.id,e)}
    }
    if(oldCurrent && oldCurrent.id!==canonical.id){
      musicCurrentId=canonical.id;
      try{await playMusicItem(canonical);if(oldTime>0&&audio)audio.currentTime=Math.min(oldTime,audio.duration||oldTime)}catch(_){ }
    }
  }
  return removed;
}
async function saveOrSyncMusicFile(file,authorHint='Không rõ tác giả',nameHint=''){
  const name=nameHint||file.name.replace(/\.[^.]+$/,'')||file.name;
  const same=await findMusicSameName(name);
  const incomingReview=itemLooksLikeReviewName(file.name)||itemLooksLikeReviewName(name);
  const existingFull=same.filter(musicHasLocalAudio).sort((a,b)=>musicFullScore(b)-musicFullScore(a)||((Number(b.size)||0)-(Number(a.size)||0)))[0]||null;
  if(incomingReview&&existingFull){return {id:existingFull.id,synced:true,keptFull:true};}
  const id=await storeFile(file,'Music');
  const fresh=await getItem(id);
  if(same.length){
    const metaSource=same.slice().sort((a,b)=>musicMetaRichness(b)-musicMetaRichness(a)||((b.createdAt||0)-(a.createdAt||0)))[0];
    fresh.name=metaSource?.name||name;
    fresh.author=metaSource?.author||authorHint||'Không rõ tác giả';
    fresh.description=metaSource?.description||'';
    fresh.lyrics=metaSource?.lyrics||'';
    fresh.coverBlob=metaSource?.coverBlob;
    fresh.coverBlob2=metaSource?.coverBlob2;
    fresh.musicOrder=metaSource?.musicOrder??0;
    fresh.source='full';fresh.remoteUrl='';fresh.syncedAt=Date.now();fresh.fullFileName=file.name;
    const wasCurrent=same.some(x=>x.id===musicCurrentId), audio=document.getElementById('musicAudio'), oldTime=audio?.currentTime||0;
    for(const old of same)try{await del(old.id)}catch(_){ }
    await saveMeta(fresh);
    if(wasCurrent){musicCurrentId=fresh.id;try{await playMusicItem(fresh);if(oldTime>0&&audio)audio.currentTime=Math.min(oldTime,audio.duration||oldTime)}catch(_){}}
    return {id:fresh.id,synced:true};
  }
  fresh.name=name;fresh.author=authorHint;fresh.source='full';fresh.remoteUrl='';fresh.musicOrder=(await getMusicItems()).length;await saveMeta(fresh);return {id:fresh.id,synced:false};
}

